<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { FolderOpened,Document,Refresh,ArrowUp,Plus } from '@element-plus/icons-vue'
import { request,post } from '../api/client'
import StatusBadge from '../components/StatusBadge.vue'
import FileBatchWorkbench from '../components/FileBatchWorkbench.vue'
import {canModify,roles} from '../files/workbench'
import type {FileCapabilities} from '../files/types'
import type { FileRoot,FileEntry,FilePlan,FileResult } from '../files/types'
const roots=ref<FileRoot[]>([]),connection=ref(''),directory=ref('.'),entries=ref<FileEntry[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref(''),filter=ref(''),history=ref<FileResult[]>([])
const currentRoot=computed(()=>roots.value.find(root=>root.id===connection.value)),shown=computed(()=>entries.value.filter(file=>file.name.toLowerCase().includes(filter.value.toLowerCase())))
const capability=ref<FileCapabilities|null>(null),selection=ref<FileEntry[]>([])
function selectMobile(file:FileEntry,checked:boolean){selection.value=selection.value.filter(row=>row.path!==file.path);if(checked)selection.value.push(file)}
let recognizeEpoch=0
const recognizing=ref(false)
const dialog=ref(false),previewDialog=ref(false),preview=ref<FilePlan|null>(null),previewing=ref(false),executing=ref(false),reconciling=ref(''),actionError=ref('')
const form=reactive({operation:'rename',source:'',destination:'.',name:'',template:'{title} ({year}){ext}',nameMode:'default',title:'',year:'',mediaType:'movie',category:'',season:1,episode:1,resolution:'',includeSidecars:true})
const actionTitle=computed(()=>({rename:'重命名',move:'移动文件 / 目录',organize:'影视分类整理',mkdir:'新建文件夹',trash:'删除（可恢复）'}[form.operation]??'文件操作'))
let sequence=0
async function load(){const id=connection.value,path=directory.value,serial=++sequence;if(!id){entries.value=[];return};loading.value=true;error.value='';try{const out=await request<{items:FileEntry[];total:number;capabilities:FileCapabilities}>(`/files?connectionId=${encodeURIComponent(id)}&path=${encodeURIComponent(path)}&page=${page.value}&pageSize=50`);if(serial!==sequence)return;entries.value=out.items;total.value=out.total;capability.value=out.capabilities;selection.value=[]}catch(e){if(serial===sequence){entries.value=[];error.value=e instanceof Error?e.message:'文件读取失败'}}finally{if(serial===sequence)loading.value=false}}
async function refreshHistory(){try{history.value=await request<FileResult[]>('/files/operations')}catch(e){error.value=e instanceof Error?e.message:'操作记录读取失败'}}
async function refresh(){try{roots.value=await request<FileRoot[]>('/files/roots');if(!roots.value.some(root=>root.id===connection.value)){connection.value=roots.value[0]?.id??'';directory.value='.';page.value=1};await load();await refreshHistory()}catch(e){error.value=e instanceof Error?e.message:'文件服务不可用'}}
function changeRoot(){selection.value=[];capability.value=null;directory.value='.';page.value=1;filter.value='';void load()}
function enter(file:FileEntry){if(!file.directory||file.unsupported)return;directory.value=file.path;page.value=1;filter.value='';void load()}
function parent(){directory.value=directory.value.includes('/')?directory.value.slice(0,directory.value.lastIndexOf('/')):'.';page.value=1;void load()}
function size(n:number){if(n<1024)return `${n} B`;const unit=Math.min(Math.floor(Math.log(n)/Math.log(1024)),4);return `${(n/1024**unit).toFixed(1)} ${['B','KiB','MiB','GiB','TiB'][unit]}`}
async function openAction(operation:string,file?:FileEntry){const epoch=++recognizeEpoch;actionError.value='';preview.value=null;Object.assign(form,{operation,source:file?.path??'',destination:operation==='organize'?'.':directory.value,name:operation==='mkdir'?'':file?.name??'',nameMode:file?.directory?'direct':'default',title:file?.name.replace(/\.[^.]+$/,'')??'',year:'',mediaType:'unknown',category:'',season:1,episode:1,resolution:'',includeSidecars:true});dialog.value=true; if(file&&!file.directory&&['rename','organize'].includes(operation)){recognizing.value=true;try{const parsed=await post<{hint:{title:string;year:string;mediaType:string;season:number;episode:number;resolution:string;warnings:string[]}}>('/media/recognize-name',{name:file.name});if(epoch!==recognizeEpoch||!dialog.value)return;Object.assign(form,{title:parsed.hint.title,year:parsed.hint.year,mediaType:parsed.hint.mediaType,season:parsed.hint.season,episode:parsed.hint.episode,resolution:parsed.hint.resolution});if(parsed.hint.warnings.length)actionError.value=parsed.hint.warnings.join('；')}catch(e){actionError.value=e instanceof Error?e.message:'文件名识别失败'}finally{recognizing.value=false}}}
async function makePreview(){if(!connection.value)return;previewing.value=true;actionError.value='';try{const {nameMode,...input}=form;const body={...input,connectionId:connection.value,name:form.nameMode==='direct'?form.name:'',template:form.nameMode==='template'?form.template:''};if(form.operation==='move'||form.operation==='trash')Object.assign(body,{name:'',template:''});preview.value=await post<FilePlan>('/files/preview',body);dialog.value=false;previewDialog.value=true}catch(e){actionError.value=e instanceof Error?e.message:'预览失败'}finally{previewing.value=false}}
async function execute(){if(!preview.value)return;executing.value=true;actionError.value='';try{const result=await post<FileResult>(`/files/operations/${preview.value.id}/execute`,{digest:preview.value.digest,confirm:true});if(result.state==='succeeded')ElMessage.success('文件操作完成，播放Key不变');else ElMessage.warning(result.message);previewDialog.value=false;preview.value=null;await load();await refreshHistory()}catch(e){actionError.value=e instanceof Error?e.message:'结果未知，请通过操作记录核对；不要重复提交';await refreshHistory()}finally{executing.value=false}}
async function reconcile(item:FileResult){try{await ElMessageBox.confirm('只检查当前源/目标身份并核对记录，不会重新发送移动或重命名请求。','核对结果',{confirmButtonText:'核对结果',cancelButtonText:'取消'})}catch{return};reconciling.value=item.id;try{const result=await post<FileResult>(`/files/operations/${item.id}/reconcile`,{});ElMessage.info(result.message);await refreshHistory();await load()}catch(e){ElMessage.error(e instanceof Error?e.message:'核对失败')}finally{reconciling.value=''}}
const stateLabel=(state:string)=>({preview:'待确认',running:'执行中',succeeded:'已核对完成',needs_reconcile:'需要核对',failed:'部分或未完成',expired:'预览过期'}[state]??state)
onMounted(refresh)
</script>
<template>
 <section class="page-heading"><div><span class="page-kicker">ORGANIZE / 文件管理</span><h1>文件管理</h1><p>浏览 115 云盘和本地目录，预览后再重命名、分类移动或移入回收目录。</p></div><el-button :icon="Refresh" :loading="loading" @click="refresh">刷新</el-button></section>
 <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
 <section class="panel file-panel">
  <div class="file-toolbar"><el-select v-model="connection" aria-label="文件根目录" placeholder="选择已启用的文件根目录" @change="changeRoot"><el-option v-for="root in roots" :key="root.id" :value="root.id" :label="`${root.kind==='cloud'?'云盘 / 115':'本地'} · ${root.name}`"/></el-select><el-button :icon="ArrowUp" :disabled="directory==='.'||loading" @click="parent">上级目录</el-button><el-button :icon="Plus" :disabled="!connection||loading||capability?.write===false||currentRoot?.capabilities?.write===false" @click="openAction('mkdir')">新建文件夹</el-button><el-input v-model="filter" aria-label="筛选当前页文件" placeholder="筛选当前页文件" clearable/></div>
  <div v-if="currentRoot" class="current-path"><span>{{currentRoot.kind==='cloud'?'CloudDrive2 / 115':'自动发现的本地目录'}}</span><code>{{currentRoot.path}}{{directory==='.'?'':'/'+directory}}</code><el-button size="small" @click="directory='.';page=1;load()">根目录</el-button><el-button size="small" @click="directory='.media-tool-trash';page=1;load()">查看回收目录</el-button></div>
  <div v-if="capability" class="capability-bar"><el-tag>{{roles[capability.role]??capability.role}}</el-tag><StatusBadge v-if="currentRoot?.connectionState" :state="currentRoot.connectionState"/><el-tag :type="capability.readOnly?'warning':'success'">{{capability.readOnly?'只读':'允许预览写入'}}</el-tag><span>{{capability.reason||'不做写入探测；执行前仍会重新校验权限和目标占用'}}</span></div>
  <FileBatchWorkbench v-if="currentRoot" :root="currentRoot" :files="selection" @completed="refresh"/>
  <el-empty v-if="!roots.length" description="尚无启用的文件根目录"><span>本地目录随应用挂载自动显示，无需绑定</span><span class="muted"> · </span><RouterLink to="/integrations?kind=clouddrive2">配置 CloudDrive2</RouterLink></el-empty>
  <el-table v-else class="desktop-files" :data="shown" v-loading="loading" empty-text="当前目录没有文件" row-key="path" @row-dblclick="enter" @selection-change="selection=$event">
   <el-table-column type="selection" width="45" :selectable="(row:FileEntry)=>!row.directory&&canModify(row)"/><el-table-column label="名称" min-width="240"><template #default="scope"><button class="file-name" :disabled="!scope.row.directory||scope.row.unsupported" @click="enter(scope.row)"><component :is="scope.row.directory?FolderOpened:Document" aria-hidden="true"/><span>{{scope.row.name}}</span></button><small v-if="scope.row.capabilities?.reason" class="muted">{{scope.row.capabilities.reason}}</small><small v-if="scope.row.unsupported" class="muted">符号链接或特殊文件：只显示名称，不允许操作</small></template></el-table-column>
   <el-table-column label="类型" width="95"><template #default="scope">{{scope.row.directory?'文件夹':'文件'}}</template></el-table-column>
   <el-table-column label="大小" width="120"><template #default="scope">{{scope.row.directory?'—':size(scope.row.size)}}</template></el-table-column>
   <el-table-column label="操作" min-width="350"><template #default="scope"><div class="file-actions"><el-button size="small" :disabled="!canModify(scope.row)" @click="openAction('rename',scope.row)">重命名</el-button><el-button size="small" :disabled="!canModify(scope.row)" @click="openAction('move',scope.row)">移动</el-button><el-button v-if="!scope.row.directory" size="small" :disabled="!canModify(scope.row)" @click="openAction('organize',scope.row)">影视整理</el-button><el-button size="small" type="danger" plain :disabled="!canModify(scope.row)||scope.row.path==='.media-tool-trash'" @click="openAction('trash',scope.row)">{{currentRoot?.kind==='local'?'删除（可恢复）':'移入回收目录'}}</el-button></div></template></el-table-column>
  </el-table><ul v-if="roots.length" class="mobile-file-list" aria-label="移动端文件列表"><li v-for="file in shown" :key="file.path"><el-checkbox v-if="!file.directory" :model-value="selection.some(row=>row.path===file.path)" :disabled="!canModify(file)" :aria-label="`选择 ${file.name}`" @change="selectMobile(file,!!$event)">选择</el-checkbox><button class="file-name" :disabled="!file.directory||file.unsupported" @click="enter(file)"><component :is="file.directory?FolderOpened:Document" aria-hidden="true"/><span>{{file.name}}</span></button><p class="field-hint">{{file.directory?'文件夹':size(file.size)}}{{file.unsupported?' · 特殊文件受保护':''}} · {{file.capabilities?.reason??'可预览操作'}}</p><div class="file-actions"><el-button size="small" :disabled="!canModify(file)" @click="openAction('rename',file)">重命名</el-button><el-button size="small" :disabled="!canModify(file)" @click="openAction('move',file)">移动</el-button><el-button v-if="!file.directory" size="small" :disabled="!canModify(file)" @click="openAction('organize',file)">影视整理</el-button><el-button size="small" type="danger" plain :disabled="!canModify(file)||file.path==='.media-tool-trash'" @click="openAction('trash',file)">{{currentRoot?.kind==='local'?'删除（可恢复）':'移入回收目录'}}</el-button></div></li><li v-if="!shown.length" class="field-hint">当前目录没有文件</li></ul><el-pagination v-if="roots.length" v-model:current-page="page" :page-size="50" :total="total" layout="prev,pager,next,total" @current-change="load"/>
 </section>
 <section class="panel section-gap"><div class="panel-title"><h2>文件操作记录</h2><el-button @click="refreshHistory">刷新记录</el-button></div><el-table :data="history" empty-text="尚无文件操作记录"><el-table-column label="操作" width="110"><template #default="scope">{{({rename:'重命名',move:'移动',organize:'影视整理',mkdir:'新建目录',trash:'回收'})[scope.row.plan.operation as string]??scope.row.plan.operation}}</template></el-table-column><el-table-column label="状态" width="145"><template #default="scope">{{stateLabel(scope.row.state)}}</template></el-table-column><el-table-column label="说明" min-width="280"><template #default="scope">{{scope.row.message||`预览包含 ${scope.row.plan.items.length} 项，尚未执行`}}</template></el-table-column><el-table-column label="结果核对" width="170"><template #default="scope"><el-button v-if="['needs_reconcile','running'].includes(scope.row.state)" size="small" :loading="reconciling===scope.row.id" @click="reconcile(scope.row)">核对结果（不重放）</el-button></template></el-table-column></el-table></section>
 <section class="note-panel"><strong>不会自动覆盖或永久删除</strong><p>云盘操作通过 CloudDrive2；目录必须在允许根目录内。做种源与托管STRM/NFO输出受保护。回收只移动至根目录内的回收目录，可通过“移动”恢复；不会永久删除文件。移动后同步云盘索引，已有文件级Key和STRM正文不变。</p></section>
 <el-dialog v-model="dialog" :title="actionTitle" width="min(680px,94vw)" top="5vh" class="file-dialog" :close-on-click-modal="false">
  <el-alert v-if="actionError" :title="actionError" type="error" :closable="false"/>
  <p v-if="form.source" class="field-hint">源文件：{{form.source}}</p>
  <el-form :disabled="recognizing" label-position="top" @submit.prevent="makePreview">
   <el-form-item v-if="!['rename','trash'].includes(form.operation)" label="目标目录（相对允许根目录）"><el-input v-model="form.destination" aria-label="目标目录" placeholder=". 表示根目录；影视整理可按下方类型自动分类"/></el-form-item>
   <template v-if="form.operation==='organize'"><el-form-item label="媒体类型"><el-radio-group v-model="form.mediaType"><el-radio value="movie">电影</el-radio><el-radio value="series">电视剧</el-radio></el-radio-group></el-form-item><div class="form-pair"><el-form-item label="影视标题"><el-input v-model="form.title" aria-label="影视标题"/></el-form-item><el-form-item label="年份"><el-input v-model="form.year" aria-label="年份" placeholder="1997"/></el-form-item></div><el-form-item label="自定义分类（可选）"><el-input v-model="form.category" aria-label="自定义分类" placeholder="动画电影、纪录片等；目标目录为 . 时自动生成分类目录"/></el-form-item><div v-if="form.mediaType==='series'" class="form-pair"><el-form-item label="季号"><el-input-number v-model="form.season" :min="0" :max="999"/></el-form-item><el-form-item label="集号（命名模板用）"><el-input-number v-model="form.episode" :min="0" :max="9999"/></el-form-item></div><el-checkbox v-model="form.includeSidecars">一并整理同名字幕与NFO侧车</el-checkbox><p class="field-hint">影视身份不会因手工重命名改变；需修改身份或NFO时请使用云盘索引中的身份修正。</p></template>
   <template v-if="['rename','organize'].includes(form.operation)"><el-form-item label="命名方式"><el-radio-group v-model="form.nameMode"><el-radio v-if="!entries.find(file=>file.path===form.source)?.directory" value="default">系统模板（默认）</el-radio><el-radio value="direct">自定义文件名</el-radio><el-radio value="template">命名模板</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.nameMode==='template'" label="命名模板"><el-input v-model="form.template" aria-label="命名模板"/><p class="field-hint">支持相对文件夹，{title}、{year}、{season}、{episode}、{season_episode}、{videoFormat}、{resolution}、{ext}；重命名只使用最后的文件名；分辨率值需明确填写，不会猜测媒体规格。</p></el-form-item><el-form-item v-if="form.nameMode!=='direct'&&form.operation==='rename'" label="标题（模板需要时）"><el-input v-model="form.title"/></el-form-item><template v-if="form.nameMode!=='direct'&&form.operation==='rename'"><el-form-item label="年份（模板需要时）"><el-input v-model="form.year" aria-label="模板年份"/></el-form-item><div class="form-pair"><el-form-item label="季号（模板需要时）"><el-input-number v-model="form.season" :min="0" :max="999"/></el-form-item><el-form-item label="集号（模板需要时）"><el-input-number v-model="form.episode" :min="0" :max="9999"/></el-form-item></div></template><el-form-item v-if="form.nameMode!=='direct'" label="分辨率（模板需要时）"><el-input v-model="form.resolution" placeholder="1080p"/></el-form-item></template>
   <el-form-item v-if="(['rename','organize','mkdir'].includes(form.operation)&&form.nameMode==='direct')||form.operation==='mkdir'" :label="form.operation==='mkdir'?'文件夹名称':'自定义文件名'"><el-input v-model="form.name" aria-label="自定义文件名"/></el-form-item>
   <el-checkbox v-if="form.operation==='rename'" v-model="form.includeSidecars">一并重命名同名字幕与NFO侧车（普通文件有效）</el-checkbox><el-alert v-if="form.operation==='trash'" title="只移入本根目录回收区，不调用永久删除。媒体入回收区后，其文件级播放入口暂不可用；恢复原文件后可继续使用原Key。" type="warning" :closable="false"/>
  </el-form><template #footer><el-button :disabled="previewing" @click="dialog=false">取消</el-button><el-button type="primary" :loading="previewing||recognizing" :disabled="recognizing" @click="makePreview">预览变更</el-button></template>
 </el-dialog>
 <el-dialog v-model="previewDialog" title="确认文件变更" width="min(800px,95vw)" top="5vh" class="file-dialog" :close-on-click-modal="false" :close-on-press-escape="!executing" :show-close="!executing">
  <el-alert v-if="actionError" :title="actionError" type="error" :closable="false"/>
  <el-alert title="请核对全部源路径和目标路径。预览未执行文件变更；确认后不会自动覆盖同名文件或重放未知结果。" type="warning" :closable="false"/>
  <ul class="file-plan"><li v-for="item in preview?.items??[]" :key="item.target"><code>{{item.source.path||'新建目录'}}</code><span aria-hidden="true">→</span><code>{{item.target}}</code></li></ul>
  <p v-if="preview?.steps.some(step=>step.action==='mkdir')" class="field-hint">同时新建：{{preview.steps.filter(step=>step.action==='mkdir').map(step=>step.target).join('、')}}</p>
  <template #footer><el-button :disabled="executing" @click="previewDialog=false">取消，不执行</el-button><el-button type="primary" :loading="executing" @click="execute">确认执行文件变更</el-button></template>
 </el-dialog>
</template>
<style scoped>
.capability-bar{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-bottom:16px;font-size:13px;line-height:1.7}.desktop-files{margin-top:16px}
.mobile-file-list .el-checkbox{min-height:44px}.mobile-file-list{display:none;list-style:none;padding:0;margin:0}.mobile-file-list li{padding:16px 0;border-bottom:1px solid var(--border)}.file-panel{margin-bottom:24px}.file-toolbar{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:16px}.file-toolbar .el-select{width:280px}.file-toolbar .el-input{width:220px;flex:1;min-width:180px}.current-path{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:12px 0 20px}.current-path code{overflow-wrap:anywhere;flex:1}.file-name{display:flex;gap:10px;align-items:center;background:none;border:0;color:var(--text);padding:8px 0;min-height:44px;text-align:left;cursor:pointer}.file-name:disabled{cursor:default;opacity:1}.file-name svg{width:20px;height:20px;flex-shrink:0;color:var(--el-color-primary)}.file-name span{overflow-wrap:anywhere}.file-actions{display:flex;flex-wrap:wrap;gap:8px}.file-actions .el-button{margin-left:0}.el-pagination{margin-top:16px;overflow:auto}.form-pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.file-plan{padding:0;list-style:none}.file-plan li{display:grid;grid-template-columns:1fr 24px 1fr;gap:12px;padding:14px 0;border-bottom:1px solid var(--border)}.file-plan code{white-space:normal;overflow-wrap:anywhere;line-height:1.6}:global(.file-dialog){max-height:90dvh;display:flex;flex-direction:column}:global(.file-dialog .el-dialog__body){min-height:0;overflow:auto;padding-bottom:24px}@media(max-width:680px){.desktop-files{display:none}.mobile-file-list{display:block}.current-path>span,.current-path code{flex-basis:100%;width:100%;min-width:0}.file-toolbar .el-select,.file-toolbar .el-input{width:100%}.file-actions .el-button{min-height:44px}:deep(.el-input__wrapper){min-height:40px}.form-pair{grid-template-columns:1fr}.file-plan li{grid-template-columns:1fr}.file-plan li>span{display:none}}
</style>
